SELECT id AS id, user_id AS userId, perm_id AS permId, field_code AS fieldCode, field_name AS fieldName, relation AS relation, rule_conditions AS ruleConditions, rule_value AS ruleValue, create_time AS createTime, create_user AS createUser, update_time AS updateTime, update_user AS updateUser, del_flag AS delFlag, version AS version, sort AS sort FROM ytsafety_sys_user_data_rule
and del_flag = 0 and rule_value !='column_hide'
and user_id = #{userId}
and perm_code = #{permCode}
ORDER BY sort ASC

SELECT id AS id, user_id AS userId, perm_id AS permId, field_code AS fieldCode, field_name AS fieldName, relation AS relation, rule_conditions AS ruleConditions, rule_value AS ruleValue, create_time AS createTime, create_user AS createUser, update_time AS updateTime, update_user AS updateUser, del_flag AS delFlag, version AS version, sort AS sort FROM ytsafety_sys_user_data_rule
del_flag = 0
AND user_id = #{userId}
AND rule_value = #{ruleValue}
AND perm_code = #{permCode}
ORDER BY sort ASC
